function assessmentIntroView() {
  const hasResume = Boolean(state.activeAssessment);
  return shell(`
    <section class="page-heading"><button class="back-button" data-route="home">← 回首頁</button><p>課堂／研究模式</p><h1>完整能力測驗</h1><span>前測 8 題 → 訓練 8 題 → 後測 8 題</span></section>
    <section class="assessment-intro"><div class="assessment-intro__timeline"><article><span>01</span><div><h2>前測</h2><p>記錄原本的安全行動、分類、證據與自信，不立即公布答案。</p></div><strong>8 題</strong></article><article><span>02</span><div><h2>訓練</h2><p>每題提供完整解析、關鍵訊號、可能後果與官方查證路徑。</p></div><strong>8 題</strong></article><article><span>03</span><div><h2>後測</h2><p>使用不同表面情境，再測一次同樣的底層能力。</p></div><strong>8 題</strong></article></div><aside class="assessment-intro__aside"><div>${icon("lock",26)}<h2>匿名、本機保存</h2><p>不收姓名、學校或聯絡方式。分頁失焦時會暫停計時。</p></div><ul><li>約 20–30 分鐘</li><li>速度不加分</li><li>可中途暫停並在本機繼續</li></ul>${hasResume?`<button class="button button--primary button--full" data-action="resume-assessment">繼續上次進度</button><button class="button button--ghost button--full" data-action="restart-assessment">重新開始</button>`:`<button class="button button--primary button--full" data-action="start-assessment">開始完整測驗</button>`}</aside></section>`);
}
function startAssessment(restart=false){if(restart||!state.activeAssessment){const phases=["pre","training","post"];state.activeAssessment={id:crypto.randomUUID(),phase:"pre",phaseIndex:0,questionIndex:0,questionOrder:Object.fromEntries(phases.map((phase)=>[phase,getQuestionsByPhase(phase).map((question)=>question.id)])),responses:[],startedAt:new Date().toISOString(),selections:blankAssessmentSelections(),step:"answer"};state=saveState(state);}currentFlow={type:"assessment"};route="assessment";startQuestionTimer();render();}
function blankAssessmentSelections(){return {actionId:null,judgment:null,signalIds:[],confidence:null};}
function currentAssessmentQuestion(){const assessment=state.activeAssessment;if(!assessment)return null;const id=assessment.questionOrder[assessment.phase][assessment.questionIndex];return getQuestionById(id);}
function assessmentView(){
  const assessment=state.activeAssessment;const question=currentAssessmentQuestion();if(!assessment||!question)return assessmentIntroView();
  const phaseLabels={pre:"前測",training:"訓練",post:"後測"};const selections=assessment.selections??blankAssessmentSelections();const phaseTotal=assessment.questionOrder[assessment.phase].length;const overallIndex=assessment.phaseIndex*8+assessment.questionIndex+(assessment.step==="feedback"?1:0);const progress=(overallIndex/24)*100;const phaseResponse=assessment.responses.at(-1);
  return shell(`<section class="flow-header"><button class="back-button" data-action="pause-assessment">← 暫停</button><div class="flow-header__center"><strong>${phaseLabels[assessment.phase]}</strong><span>第 ${assessment.questionIndex+1}／${phaseTotal} 題 · 總進度 ${Math.min(24,overallIndex+1)}／24</span></div><span class="phase-badge phase-badge--${assessment.phase}">${phaseLabels[assessment.phase]}</span></section><div class="progress"><span style="width:${progress}%"></span></div><section class="research-question"><article class="scenario-card scenario-card--wide"><div class="scenario-card__header"><span class="avatar">${question.senderLabel.slice(0,1)}</span><div><strong>${question.senderLabel}</strong><small>${question.category} · 模擬情境</small></div></div><div class="scenario-card__message"><strong>${question.title}</strong><p>${question.message}</p></div><p class="scenario-card__note">此為合成練習情境，不是真實帳號或連結。</p></article>${assessment.step==="feedback"?feedbackPanel(question,phaseResponse,false):`<div class="research-form"><section class="research-step"><div class="research-step__heading"><span>1</span><div><h2>最安全的下一步</h2><p>選一項。</p></div></div><div class="option-list option-list--compact">${question.actionOptions.map((option)=>`<button class="option ${selections.actionId===option.id?"is-selected":""}" data-assessment-action="${option.id}"><span class="option__radio"></span><span>${option.label}</span></button>`).join("")}</div></section><section class="research-step"><div class="research-step__heading"><span>2</span><div><h2>目前應如何分類？</h2><p>不是所有情境都能直接判定。</p></div></div><div class="judgment-grid">${Object.entries(JUDGMENT_LABELS).map(([key,label])=>`<button class="judgment judgment--${key} ${selections.judgment===key?"is-selected":""}" data-assessment-judgment="${key}">${label}</button>`).join("")}</div></section><section class="research-step"><div class="research-step__heading"><span>3</span><div><h2>哪些訊號支持你的判斷？</h2><p>可複選。</p></div></div><div class="signal-grid">${question.signalOptions.map((option)=>`<button class="signal-option ${selections.signalIds.includes(option.id)?"is-selected":""}" data-assessment-signal="${option.id}"><small>${SIGNAL_CATEGORY_LABELS[option.category]}</small><span>${option.label}</span></button>`).join("")}</div></section><section class="research-step"><div class="research-step__heading"><span>4</span><div><h2>你有多確定？</h2><p>1 是很不確定，4 是很確定。</p></div></div><div class="confidence-grid">${[1,2,3,4].map((value)=>`<button class="confidence ${selections.confidence===value?"is-selected":""}" data-assessment-confidence="${value}"><strong>${value}</strong><span>${["很不確定","有點不確定","有點確定","很確定"][value-1]}</span></button>`).join("")}</div></section><button class="button button--primary button--full" data-action="submit-assessment" ${!selections.actionId||!selections.judgment||selections.signalIds.length===0||!selections.confidence?"disabled":""}>提交這題 ${icon("arrow",19)}</button></div>`}</section>`,{compact:true});
}
function assessmentPhaseCompleteView(phase){const labels={pre:"前測完成",training:"訓練完成",post:"完整測驗完成"};const descriptions={pre:"前測不公布答案。接下來進入訓練階段，每題會有完整解析。",training:"接下來使用不同情境進行後測，檢查是否能把原理用在新問題。",post:"現在可以查看三分類校準、安全行動、關鍵訊號與高自信錯誤。"};return shell(`<section class="completion-card"><div class="completion-card__icon">${icon(phase==="post"?"chart":"check",42)}</div><p class="completion-card__meta">${phase==="post"?"24 題全部完成":"階段完成"}</p><h1>${labels[phase]}</h1><p>${descriptions[phase]}</p><button class="button button--primary" data-action="continue-phase">${phase==="post"?"查看結果":"進入下一階段"} ${icon("arrow",19)}</button></section>`,{compact:true});}
function finishAssessment(){const assessment=state.activeAssessment;state.sessions.push({id:assessment.id,mode:"assessment",startedAt:assessment.startedAt,completedAt:new Date().toISOString(),appVersion:APP_VERSION,questionBankVersion:QUESTION_BANK_VERSION,questionOrder:Object.values(assessment.questionOrder).flat(),responses:assessment.responses});state.activeAssessment=null;state=saveState(state);currentFlow=null;route="dashboard";render();}
